package main

import (
	"fmt"

	"github.com/gzhysuiioo/payflow-settlement/payflow"
)

const configJSON = `{
  "flags": [
    {
      "key": "guest-checkout",
      "enabled": true,
      "default": true,
      "rules": [
        {
          "id": "r-block-guest",
          "value": false,
          "conditions": [
            {"attribute": "plan", "op": "eq", "value": "pro"},
            {"attribute": "tier", "op": "in", "value": ["", "a", "a"]}
          ]
        }
      ]
    }
  ]
}`

func main() {
	cfg, err := payflow.ParseConfig([]byte(configJSON))
	if err != nil {
		panic(err)
	}
	flag := cfg.Find("guest-checkout")
	if flag == nil {
		panic("flag not found")
	}

	ctxMissing, err := payflow.ParseContext([]byte(`{"plan":"pro"}`))
	if err != nil {
		panic(err)
	}
	ctxEmpty, err := payflow.ParseContext([]byte(`{"plan":"pro","tier":""}`))
	if err != nil {
		panic(err)
	}

	fmt.Println("===== plain: missing tier =====")
	plainMissing := flag.Evaluate(ctxMissing)
	fmt.Printf("Key=%q Value=%v Reason=%q RuleID=%v\n",
		plainMissing.Key, plainMissing.Value, plainMissing.Reason, plainMissing.RuleID)
	b, _ := payflow.MarshalResult(plainMissing)
	fmt.Println(string(b))

	fmt.Println("===== plain: explicit empty tier =====")
	plainEmpty := flag.Evaluate(ctxEmpty)
	var ruleID string
	if plainEmpty.RuleID != nil {
		ruleID = *plainEmpty.RuleID
	}
	fmt.Printf("Key=%q Value=%v Reason=%q RuleID=%q\n",
		plainEmpty.Key, plainEmpty.Value, plainEmpty.Reason, ruleID)
	b, _ = payflow.MarshalResult(plainEmpty)
	fmt.Println(string(b))

	fmt.Println("===== explain: missing tier =====")
	expMissing := flag.EvaluateExplain(ctxMissing)
	c0 := expMissing.Explanation.Rules[0].Conditions[0]
	c1 := expMissing.Explanation.Rules[0].Conditions[1]
	fmt.Printf("Outcome=%q\n", expMissing.Explanation.Outcome)
	fmt.Printf("c0: Attribute=%q Op=%q CompareValue=%#v ActualValue=%#v Missing=%v Match=%v\n",
		c0.Attribute, c0.Op, c0.CompareValue, c0.ActualValue, c0.Missing, c0.Match)
	fmt.Printf("c1: Attribute=%q Op=%q CompareValue=%#v ActualValue=%#v Missing=%v Match=%v\n",
		c1.Attribute, c1.Op, c1.CompareValue, c1.ActualValue, c1.Missing, c1.Match)
	b, _ = payflow.MarshalExplain(expMissing)
	fmt.Println(string(b))

	fmt.Println("===== explain: explicit empty tier =====")
	expEmpty := flag.EvaluateExplain(ctxEmpty)
	e1 := expEmpty.Explanation.Rules[0].Conditions[1]
	fmt.Printf("Outcome=%q\n", expEmpty.Explanation.Outcome)
	fmt.Printf("e1: CompareValue=%#v ActualValue=%#v Missing=%v Match=%v\n",
		e1.CompareValue, e1.ActualValue, e1.Missing, e1.Match)
	b, _ = payflow.MarshalExplain(expEmpty)
	fmt.Println(string(b))

	fmt.Println("===== independence: mutate expMissing only =====")
	before, _ := payflow.MarshalExplain(expEmpty)
	// 改文字
	expMissing.Explanation.Outcome = "rewritten by the caller"
	// 改缺失条件的实际值
	hack := "injected"
	expMissing.Explanation.Rules[0].Conditions[1].ActualValue = &hack
	// 就地改 in 候选
	list := expMissing.Explanation.Rules[0].Conditions[1].CompareValue.([]string)
	list[0] = "x"
	after, _ := payflow.MarshalExplain(expEmpty)
	fmt.Printf("sibling record unchanged: %v\n", string(before) == string(after))
	// 配置的候选未受影响
	fresh := flag.EvaluateExplain(ctxMissing)
	fb, _ := payflow.MarshalExplain(fresh)
	orig, _ := payflow.MarshalExplain(flag.EvaluateExplain(ctxMissing))
	fmt.Printf("fresh re-evaluation unaffected: %v\n", string(fb) == string(orig))
	fmt.Printf("config candidates still: %#v\n",
		fresh.Explanation.Rules[0].Conditions[1].CompareValue)
	// 保存的记录保留改写
	fmt.Printf("saved record outcome now: %q\n", expMissing.Explanation.Outcome)

	// 换上下文再求值：保存的 expEmpty 仍是当时的 false/r-block-guest
	switchCtx, _ := payflow.ParseContext([]byte(`{"plan":"free","tier":""}`))
	fresh2 := flag.EvaluateExplain(switchCtx)
	fmt.Printf("new context: Value=%v Reason=%q RuleID=%v\n",
		fresh2.Value, fresh2.Reason, fresh2.RuleID)
	fmt.Printf("saved expEmpty still: Value=%v Reason=%q RuleID=%q\n",
		expEmpty.Value, expEmpty.Reason, *expEmpty.RuleID)

	fmt.Println("===== plain struct assignment shares nested data =====")
	a := flag.EvaluateExplain(ctxEmpty)
	cp := a
	cp.Explanation.Rules[0].Conditions[1].CompareValue = []string{"z"}
	_, aList := a.Explanation.Rules[0].Conditions[1].CompareValue.([]string)
	fmt.Printf("a sees cp's edit? %v (len a list=%d)\n", aList, len(a.Explanation.Rules[0].Conditions[1].CompareValue.([]string)))
	freshA := flag.EvaluateExplain(ctxEmpty)
	fmt.Printf("fresh eval candidate list: %#v\n", freshA.Explanation.Rules[0].Conditions[1].CompareValue)

	fmt.Println("===== errors =====")
	if _, err := payflow.LoadConfig("no-such-config.json"); err != nil {
		fmt.Printf("LoadConfig: %v\n", err)
	}
	if _, err := payflow.LoadContext("no-such-context.json"); err != nil {
		fmt.Printf("LoadContext: %v\n", err)
	}
	if _, err := payflow.ParseContext([]byte(`{"plan":false}`)); err != nil {
		fmt.Printf("ParseContext: %v\n", err)
	}
	if f := cfg.Find("does-not-exist"); f == nil {
		fmt.Println(`flag key "does-not-exist" not found; stop, no evaluation`)
	}
}

