	"github.com/gzhysuiioo/payflow-settlement/payflow"
)

func main() {
	// 入口一：直接吃 JSON 字节（不碰文件系统）。
	goodConfig := []byte(`{"flags":[{"key":"f","enabled":true,"default":true,"rules":[
	  {"id":"r-ok","value":false,"conditions":[
	    {"attribute":"plan","op":"eq","value":"pro"}]}]}]}`)
	cfg, err := payflow.ParseConfig(goodConfig)
	if err != nil {
		fmt.Println("stop, no result:", err)
		return
	}
	ctx, err := payflow.ParseContext([]byte(`{"plan":"pro"}`))
	if err != nil {
		fmt.Println("stop, no result:", err)
		return
	}
	if flag := cfg.Find("f"); flag != nil {
		r := flag.Evaluate(ctx)
		b, _ := payflow.ParseContext([]byte(`{"plan":"pro"}`))
		_ = b
		// 合法规则返回 false 仍是成功结果：reason=rule，不是错误。
		fmt.Printf("legal false is success: value=%v reason=%q\n", r.Value, r.Reason)
	}

	// 入口二：读本地文件，复用同一套严格校验。
	_, err = payflow.LoadConfig("no-such-config.json")
		if err != nil {
		fmt.Println("stop, no result:", err)
	}
	_, err = payflow.LoadContext("no-such-context.json")
	if err != nil {
		fmt.Println("stop, no stop, no result:", err)
	}
	// 写一个值不是字符串的上下文到临时文件，演示 ParseContext 的类型错误原样保留。
	tmp := "/tmp/payflow-readme-demo/errors/context-bad.json"
	_ = os.WriteFile(tmp, []byte(`{"plan":false}`), 0o644)
	_, err = payflow.LoadContext(tmp)
	if err != nil {
		fmt.Println("stop, no result:", err)
	}

	// 查不到开关：明确告知未找到，不当成 false、不继续求值。
	if f := cfg.Find("absent-flag"); f == nil {
		fmt.Println(`flag key "absent-flag" not found; stop, do not treat as false`)
	}
}

